import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),n={name:"changelog.md"};function s(i,e,l,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to mumble-speech are documented here. The format follows <a href="https://keepachangelog.com/en/1.1.0/" target="_blank" rel="noreferrer">Keep a Changelog</a> and the project uses <a href="https://semver.org/" target="_blank" rel="noreferrer">Semantic Versioning</a>. Every pull request that changes behavior or public API adds an entry to <em>Unreleased</em>.</p><h2 id="unreleased" tabindex="-1"><a href="https://github.com/basteez/mumble-speech/compare/v0.1.0...HEAD" target="_blank" rel="noreferrer">Unreleased</a> <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;[Unreleased]&quot;">​</a></h2><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Release notes link the release on every registry (npm, crates.io, docs.rs, the Unity and Godot branches).</li><li>Tags with a suffix such as <code>v0.2.0-rc.1</code> are published as prereleases: npm dist-tag <code>next</code>, a crates.io prerelease, and the Unity and Godot branches stay on the last stable release.</li><li>Publishing to npm and crates.io uses trusted publishing (OIDC): no tokens are stored.</li><li>The Godot addon is on the <a href="https://godotengine.org/asset-library/asset/5553" target="_blank" rel="noreferrer">Godot Asset Library</a> and the Unity package on <a href="https://openupm.com/packages/com.mumble-speech.unity/" target="_blank" rel="noreferrer">OpenUPM</a>.</li></ul><h2 id="_0-1-0-2026-10-24" tabindex="-1"><a href="https://github.com/basteez/mumble-speech/releases/tag/v0.1.0" target="_blank" rel="noreferrer">0.1.0</a> - 2026-10-24 <a class="header-anchor" href="#_0-1-0-2026-10-24" aria-label="Permalink to &quot;[0.1.0] - 2026-10-24&quot;">​</a></h2><p>First release: one Rust core that turns text into video-game mumble speech, with bindings for the web, Godot, Unity and C.</p><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Three styles</strong>: <code>beep</code> (one beep per letter, like Undertale), <code>grunt</code> (four grunts per voice, never the same twice in a row, like Banjo-Kazooie) and <code>alphabet</code> (a vowel-based sound for every letter, Italian vowels, like Animal Crossing).</li><li><strong>Voice</strong>: pitch (−12…+12 semitones), speed (5–30 characters per second), variation (0–1) and seed; invalid values are rejected with typed errors.</li><li><strong>Two ways to use it</strong>: render a whole line (samples plus a timeline of events with start, duration, position in the text and sound identifier), or a typewriter speaker that returns one character&#39;s sound and how long to wait before the next. Both give the same samples, bit for bit.</li><li><strong>Sound identifier</strong> on every event (style and variant: which grunt, which letter, or the neutral sound), so hosts can drive mouth shapes or effects. Nothing is drawn by the library.</li><li><strong>Determinism</strong>: same input, same samples on Linux, Windows, macOS (Apple Silicon and Intel) and WebAssembly, checked in CI by 34 shared conformance vectors through every binding.</li><li><strong>Web</strong>: <code>@mumble-speech/web</code>, WebAssembly inlined (works in browsers and Node ≥ 20 with any bundler, about 57 KB gzip), TypeScript API, <code>WebAudioPlayer</code>, WAV export.</li><li><strong>Godot 4.3+</strong>: GDExtension addon with <code>MumbleVoice</code>, <code>MumbleSpeaker</code> (<code>say</code>, <code>speak_character</code>, signals on the audio clock) and <code>MumbleTypewriter</code> for <code>Label</code>/<code>RichTextLabel</code>; Windows x64, macOS universal, Linux x64.</li><li><strong>Unity 2022.3+</strong>: UPM package with <code>MumbleVoice</code>, <code>MumbleSpeaker</code>, an optional TextMeshPro typewriter, a sample, EditMode tests, and a <code>UnityEngine</code>-free C# API; Windows x64, macOS universal, Linux x64.</li><li><strong>C ABI</strong> (version 2): <code>mumble.h</code> with render, events, typewriter speaker and WAV encoding; status codes, no panics across the boundary; shared libraries for Windows x64, macOS universal and Linux x64.</li><li><strong>Documentation and playground</strong> at <a href="https://mumble-speech.github.io/" target="_blank" rel="noreferrer">https://mumble-speech.github.io/</a>.</li><li><strong>Distribution</strong>: npm (<code>@mumble-speech/web</code>), crates.io (<code>mumble-speech</code>), Unity by git URL (branch <code>upm</code>), Godot addon on branch <code>godot-addon</code>, and release archives with checksums.</li></ul><h3 id="known-issues" tabindex="-1">Known issues <a class="header-anchor" href="#known-issues" aria-label="Permalink to &quot;Known issues&quot;">​</a></h3><ul><li>The Unity components, sample and TextMeshPro typewriter have not been checked in the Unity editor yet (the C# interop layer is tested in CI); please report problems.</li><li>macOS may quarantine libraries downloaded from the browser. If Godot or Unity cannot load them, run <code>xattr -dr com.apple.quarantine</code> on the extracted folder.</li><li>Desktop only: no prebuilt libraries for iOS, Android or consoles, no Godot web export or Unity WebGL support yet.</li><li>The OpenUPM and Godot Asset Library entries are submitted after this release and appear once approved; until then use the git URL (Unity) or the release zip (Godot).</li></ul>',11)])])}const g=a(n,[["render",s]]);export{u as __pageData,g as default};
